import React from "react";
import {
  FormItem,
  FormButtonGroup,
  Submit,
  ArrayTabs,
  Input,
} from "@storage-fe/formily-arco";
import { createForm } from "@formily/core";
import { FormProvider, Field, ArrayField, ObjectField } from "@formily/react";

const form = createForm();

export default () => (
  <FormProvider form={form}>
    <ArrayField
      name="string_array"
      title={"字符串数组"}
      decorator={[FormItem]}
      component={[ArrayTabs, { mode: "jsx" }]}
    >
      <Field
        name="input"
        title={"字符串"}
        decorator={[FormItem]}
        component={[Input]}
      ></Field>
    </ArrayField>
    <ArrayField
      name="object_array"
      title={"对象数组"}
      decorator={[FormItem]}
      component={[ArrayTabs, { mode: "jsx" }]}
    >
      <ObjectField name="object">
        <Field
          name="input1"
          title={"字符串1"}
          decorator={[FormItem]}
          component={[Input]}
        />
        <Field
          name="input2"
          title={"字符串2"}
          decorator={[FormItem]}
          component={[Input]}
        />
      </ObjectField>
    </ArrayField>
    <FormButtonGroup>
      <Submit onSubmit={console.log}>Submit</Submit>
    </FormButtonGroup>
  </FormProvider>
);
